import math
def priority(task, state, c=1.0, u=10.0, L=1000.0, d=10.0):
    est = max(task.estimated_runtime, 1e-6)
    if task.due <= state.now:
        return -L - est
    slack = task.due - state.now - est
    scale = max(state.mean_est, est, 1e-6)
    if slack < 0.0:
        return -d - est
    urgency = math.exp(-slack / max(c * scale, 1e-6))
    return -est + u * urgency  # tuned (c=3.81,u=2.8,L=351,d=9.06)

def priority(task, state, guard=1000.0, h=1.0, k=2.0, prem=5.0, std=0.0, pad=1.0):
    import math
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - pad * est
    wait_scale = max(state.mean_est, state.queue_work / max(state.capacity, 1e-6), 1e-6)
    margin = h * wait_scale
    base = -est
    if slack < 0.0:
        return base
    if slack < margin:
        mult = prem if task.tenant == 'premium' else std
        return base + guard * mult * math.exp(-slack / max(k * wait_scale, 1e-6))
    return base

