def priority(task, state, k=4.0, m=2.0, late_scale=2.0, mem_pow=0.3, mem_slack=2.0, guard=2.0, guard_slack=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    need = max(task.resource_need, 1e-6)
    slack = task.due - est - state.now

    if slack >= 0.0:
        urgency = math.exp(-slack / (max(k, 1e-6) * mean))
    else:
        urgency = math.exp(slack / (max(late_scale, 1e-6) * mean))

    mem_factor = 1.0
    if slack > mem_slack * mean:
        mem_factor = 1.0 / (need ** max(mem_pow, 0.0))

    tier = m if task.tenant == 'premium' else 1.0
    score = tier * task.weight / est * urgency * mem_factor

    if 0.0 <= slack < guard_slack * est:
        score *= (1.0 + guard)

    return score  # tuned (k=4.48,m=2.73,late_scale=1.1,mem_pow=0.35,mem_slack=3.82,guard=0.868,guard_slack=0.521)

