    if pressure > 0.0:
        return atc + c * tier * (1.0 + pressure / mean) / est
    if load > q:
        return atc * (1.0 + c * load)
    return atc  # tuned (k=3.76,m=1.36,q=0.419,b=0.33,c=16)

