def priority(task, state, k=1.0, m=2.0, b=1.0, tenant_slack=2.0, urg_boost=1.0, doom_pen=0.01):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    wait = max(0.0, state.now - task.release)
    tier = m if (task.tenant == 'premium' and slack < tenant_slack * mean) else 1.0
    age = 1.0 + b * wait / est
    base = tier * task.weight / est * math.exp(-max(0.0, slack) / max(k * mean, 1e-6)) * age
    if task.due < state.now or slack < -mean:
        return base * doom_pen / max(1.0 + max(0.0, -slack) / mean, 1e-6)
    base *= 1.0 + urg_boost / max(1.0 + max(0.0, slack) / est, 1e-6)
    return base  # tuned (k=0.494,m=3.2,b=1.01,tenant_slack=0.983,urg_boost=0.936,doom_pen=0.00734)

